//! Exports against the gate's databases ([Testing](../docs/standards/testing.md#full-mode)).
//!
//! `cargo xtask check --full` runs these for every fixture with
//! `JYKRE_TEST_DRIVER` (`postgres` or `mysql`) and `JYKRE_TEST_PORT`; they
//! are ignored otherwise. The rows are generated by the statement itself, so
//! no seed is needed: 250,000 rows of about 220 bytes, read in several parts.
#![cfg_attr(test, allow(clippy::unwrap_used, clippy::expect_used))]
use jykre::backend::{self, ExportProgress, ExportRead, ExportRequest};
use jykre::drivers::*;
use jykre::export::{ExportFormat, ExportOptions, SqlTarget};
use jykre::result::{DEFAULT_MEMORY_CEILING, ResultBuilder, ResultData};
use serde_json::json;
use std::path::{Path, PathBuf};
use std::sync::Arc;

const ROWS: u64 = 250_000;

struct Fixture {
    driver: Arc<dyn Driver>,
    input: ResolvedConnection,
    sql: String,
}

fn fixture() -> Fixture {
    let port: u16 = std::env::var("JYKRE_TEST_PORT")
        .expect("JYKRE_TEST_PORT must name the fixture port (see docs/standards/testing.md)")
        .parse()
        .expect("JYKRE_TEST_PORT must be a valid port");
    let driver = std::env::var("JYKRE_TEST_DRIVER")
        .expect("JYKRE_TEST_DRIVER must be postgres or mysql (see docs/standards/testing.md)");
    let credentials = Credentials {
        password: Some(SecretString::from("jykre-test".to_owned())),
    };
    match driver.as_str() {
        "postgres" => Fixture {
            driver: Arc::new(PostgresDriver),
            input: ResolvedConnection {
                config: ConnectionConfig {
                    driver: DriverKind::Postgres,
                    options: json!({"host":"127.0.0.1","port":port,"database":"jykre","user":"jykre","sslMode":"disable"}),
                },
                credentials,
            },
            sql: format!(
                "SELECT n, 'row ' || n AS note, repeat('x', 200) AS padding, \
                 (n::numeric / 7)::numeric(20,10) AS ratio \
                 FROM generate_series(1, {ROWS}) AS n ORDER BY n"
            ),
        },
        other => {
            assert_eq!(
                other, "mysql",
                "JYKRE_TEST_DRIVER must be postgres or mysql"
            );
            let digits = "(SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 \
                 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 \
                 UNION ALL SELECT 8 UNION ALL SELECT 9)";
            Fixture {
                driver: Arc::new(MySqlDriver),
                input: ResolvedConnection {
                    config: ConnectionConfig {
                        driver: DriverKind::MySql,
                        options: json!({"host":"127.0.0.1","port":port,"database":"jykre","user":"jykre","sslMode":"required"}),
                    },
                    credentials,
                },
                sql: format!(
                    "SELECT n, CONCAT('row ', n) AS note, REPEAT('x', 200) AS padding, \
                     CAST(CAST(n AS DECIMAL(30,15)) / 7 AS DECIMAL(20,10)) AS ratio \
                     FROM (SELECT a.d + 10 * b.d + 100 * c.d + 1000 * e.d + 10000 * f.d \
                     + 100000 * g.d AS n FROM {digits} a CROSS JOIN {digits} b \
                     CROSS JOIN {digits} c CROSS JOIN {digits} e CROSS JOIN {digits} f \
                     CROSS JOIN {digits} g) AS numbers WHERE n BETWEEN 1 AND {ROWS} ORDER BY n"
                ),
            }
        }
    }
}

fn options(max_rows: u32) -> ExecutionOptions {
    ExecutionOptions {
        max_rows,
        ..ExecutionOptions::default()
    }
}

/// Runs the statement in a new session and keeps its first page, as a tab
/// does.
async fn first_page(fixture: &Fixture) -> (Box<dyn Session>, ResultData) {
    let mut session = fixture
        .driver
        .open_session(&fixture.input, CancellationToken::new())
        .await
        .unwrap();
    let mut builder = ResultBuilder::new(1_000, DEFAULT_MEMORY_CEILING);
    let outcome = session
        .execute(
            &QueryRequest {
                parameters: Vec::new(),
                sql: fixture.sql.clone(),
                options: options(1_000),
            },
            &mut builder,
            CancellationToken::new(),
        )
        .await
        .unwrap();
    assert!(outcome.has_more);
    let (data, _) = builder.finish();
    assert_eq!(data.row_count(), 1_000);
    (session, data)
}

fn scratch(name: &str) -> PathBuf {
    let dir =
        std::env::temp_dir().join(format!("jykre-live-export-{name}-{}", ConnectionId::new()));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

fn names(dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(dir)
        .unwrap()
        .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    names
}

fn request(
    target: PathBuf,
    format: ExportFormat,
    page: ResultData,
    read: ExportRead,
) -> ExportRequest {
    ExportRequest {
        target,
        options: ExportOptions {
            format,
            ..ExportOptions::default()
        },
        columns: page.columns().to_vec(),
        sql: SqlTarget::default(),
        pages: vec![Arc::new(page)],
        read,
    }
}

/// The session still runs statements after the export.
async fn answers(session: &mut Box<dyn Session>) {
    let mut builder = ResultBuilder::new(10, DEFAULT_MEMORY_CEILING);
    session
        .execute(
            &QueryRequest {
                parameters: Vec::new(),
                sql: "SELECT 1".into(),
                options: options(10),
            },
            &mut builder,
            CancellationToken::new(),
        )
        .await
        .unwrap();
    assert_eq!(builder.finish().0.value(0, 0), Some("1"));
}

#[tokio::test]
#[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
async fn the_rest_of_an_open_result_goes_to_the_file_in_order() {
    let fixture = fixture();
    let (session, page) = first_page(&fixture).await;
    let dir = scratch("rest");
    let target = dir.join("numbers.csv");
    let run = backend::export(
        request(
            target.clone(),
            ExportFormat::Csv,
            page,
            ExportRead::Rest {
                session,
                options: options(1_000),
            },
        ),
        CancellationToken::new(),
        None,
    )
    .await;
    let exported = run.outcome.unwrap();
    assert_eq!(exported.rows, ROWS);
    assert!(!exported.truncated);
    let text = std::fs::read_to_string(&target).unwrap();
    let mut lines = text.lines();
    assert_eq!(lines.next(), Some("\"n\";\"note\";\"padding\";\"ratio\""));
    let mut expected = 0u64;
    for line in lines {
        expected += 1;
        let fields: Vec<&str> = line
            .split(';')
            .map(|field| field.trim_matches('"'))
            .collect();
        assert_eq!(fields[0].parse::<u64>().unwrap(), expected);
        assert_eq!(fields[1], format!("row {expected}"));
        assert_eq!(fields[2].len(), 200);
        // Exact decimals, as the server wrote them.
        if expected == 1 {
            assert_eq!(fields[3], "0.1428571429");
        }
        if expected == ROWS {
            assert_eq!(fields[3], "35714.2857142857");
        }
    }
    assert_eq!(expected, ROWS);
    assert_eq!(exported.bytes, text.len() as u64);
    assert_eq!(names(&dir), ["numbers.csv"]);
    let mut session = run.session.expect("the session comes back");
    assert!(run.context.is_some());
    answers(&mut session).await;
    session.close().await.unwrap();
    std::fs::remove_dir_all(dir).unwrap();
}

#[tokio::test]
#[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
async fn a_statement_run_again_goes_to_an_excel_file() {
    let fixture = fixture();
    let (session, page) = first_page(&fixture).await;
    let dir = scratch("again");
    let target = dir.join("numbers.xlsx");
    let run = backend::export(
        request(
            target.clone(),
            ExportFormat::Xlsx,
            page,
            ExportRead::Again {
                input: fixture.input.clone(),
                session: Some(session),
                sql: fixture.sql.clone(),
                parameters: Vec::new(),
                options: options(1_000),
            },
        ),
        CancellationToken::new(),
        None,
    )
    .await;
    let exported = run.outcome.unwrap();
    assert_eq!(exported.rows, ROWS);
    assert!(!run.reopened);
    assert!(std::fs::read(&target).unwrap().starts_with(b"PK\x03\x04"));
    assert_eq!(names(&dir), ["numbers.xlsx"]);
    let mut session = run.session.expect("the session comes back");
    answers(&mut session).await;
    session.close().await.unwrap();
    std::fs::remove_dir_all(dir).unwrap();
}

#[tokio::test]
#[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
async fn a_cancelled_export_leaves_the_file_as_it_was_and_the_session_answers() {
    let fixture = fixture();
    let (session, page) = first_page(&fixture).await;
    let dir = scratch("cancel");
    let target = dir.join("numbers.json");
    std::fs::write(&target, "previous export").unwrap();
    let cancel = CancellationToken::new();
    let (progress, mut watched) = tokio::sync::watch::channel(ExportProgress::default());
    // The user cancels once the first part read from the server is written.
    let canceller = {
        let cancel = cancel.clone();
        tokio::spawn(async move {
            while watched.changed().await.is_ok() {
                if watched.borrow().rows > 1_000 {
                    cancel.cancel();
                    break;
                }
            }
        })
    };
    let run = backend::export(
        request(
            target.clone(),
            ExportFormat::Json,
            page,
            ExportRead::Rest {
                session,
                options: options(1_000),
            },
        ),
        cancel,
        Some(progress),
    )
    .await;
    canceller.await.unwrap();
    assert_eq!(run.outcome.unwrap_err().code, ErrorCode::Cancelled);
    assert_eq!(names(&dir), ["numbers.json"]);
    assert_eq!(std::fs::read_to_string(&target).unwrap(), "previous export");
    // The driver brings the session back to a known state, or closes it.
    match run.session {
        Some(mut session) => {
            answers(&mut session).await;
            session.close().await.unwrap();
        }
        None => assert!(run.ended),
    }
    std::fs::remove_dir_all(dir).unwrap();
}

// ---------------------------------------------------------------------------
// Automation SQL Job proof of concept (docs/plans/automation-sql-job-poc.md):
// experiments E2, E3, E5 and E9 against the gate's databases.

mod automation {
    use super::{Fixture, fixture, options};
    use jykre::automation::{Cause, Engine, RunOutcome, RunRequest, RunState, SqlJob};
    use jykre::drivers::*;
    use jykre::result::{DEFAULT_MEMORY_CEILING, ResultBuilder, ResultData};
    use std::collections::HashMap;
    use std::sync::Arc;
    use std::time::Duration;

    const DIGITS: &str = "(SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 \
         UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 \
         UNION ALL SELECT 8 UNION ALL SELECT 9)";

    fn mysql(fixture: &Fixture) -> bool {
        fixture.input.config.driver == DriverKind::MySql
    }

    fn name(prefix: &str) -> String {
        format!(
            "{prefix}_{}",
            ConnectionId::new().to_string().replace('-', "")
        )
    }

    async fn on(session: &mut Box<dyn Session>, sql: &str) -> ResultData {
        let mut builder = ResultBuilder::new(1_000, DEFAULT_MEMORY_CEILING);
        session
            .execute(
                &QueryRequest::new(sql, options(1_000)),
                &mut builder,
                CancellationToken::new(),
            )
            .await
            .map_err(|error| format!("{sql}: {error}"))
            .unwrap();
        builder.finish().0
    }

    /// Runs `statements` in order on a session of their own, as setup.
    async fn setup(fixture: &Fixture, statements: &[String]) {
        let mut session = fixture
            .driver
            .open_session(&fixture.input, CancellationToken::new())
            .await
            .unwrap();
        for sql in statements {
            on(&mut session, sql).await;
        }
        session.close().await.unwrap();
    }

    /// A table `t` of 10,000 rows, `v` all zero.
    fn numbers(fixture: &Fixture, table: &str) -> Vec<String> {
        let fill = if mysql(fixture) {
            format!(
                "INSERT INTO {table} (id, v) SELECT a.d + 10 * b.d + 100 * c.d + 1000 * e.d + 1, 0 \
                 FROM {DIGITS} a CROSS JOIN {DIGITS} b CROSS JOIN {DIGITS} c CROSS JOIN {DIGITS} e"
            )
        } else {
            format!("INSERT INTO {table} (id, v) SELECT n, 0 FROM generate_series(1, 10000) AS n")
        };
        vec![
            format!("CREATE TABLE {table} (id INTEGER PRIMARY KEY, v INTEGER NOT NULL)"),
            fill,
        ]
    }

    async fn run(engine: &Engine, fixture: &Fixture, job: SqlJob) -> Arc<RunOutcome> {
        let mut handle = engine
            .submit(RunRequest {
                job,
                driver: fixture.driver.clone(),
                connection: fixture.input.clone(),
                values: HashMap::new(),
            })
            .unwrap();
        handle.finished().await.unwrap()
    }

    async fn scalar(engine: &Engine, fixture: &Fixture, sql: String) -> Option<String> {
        let outcome = run(engine, fixture, SqlJob::new(ConnectionId::new(), sql)).await;
        assert_eq!(outcome.state, RunState::Succeeded, "{:?}", outcome.error);
        outcome.data.value(0, 0).map(str::to_owned)
    }

    /// The distinct values of `v`, comma-separated.
    fn distinct_v(fixture: &Fixture, table: &str) -> String {
        if mysql(fixture) {
            format!("SELECT GROUP_CONCAT(DISTINCT v) FROM {table}")
        } else {
            format!("SELECT string_agg(DISTINCT v::text, ',') FROM {table}")
        }
    }

    /// E2: a write that returns more rows than the limit is read to its end
    /// and succeeds. MySQL has no `RETURNING`: a procedure writes, then
    /// returns the rows.
    #[tokio::test]
    #[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
    async fn a_job_write_beyond_the_limit_completes() {
        let fixture = fixture();
        let engine = Engine::new(tokio::runtime::Handle::current());
        let table = name("job_e2");
        let procedure = name("job_e2_p");
        let mut statements = numbers(&fixture, &table);
        let sql = if mysql(&fixture) {
            statements.push(format!(
                "CREATE PROCEDURE {procedure}() BEGIN UPDATE {table} SET v = v + 1; \
                 SELECT id FROM {table} ORDER BY id; END"
            ));
            format!("CALL {procedure}()")
        } else {
            format!("UPDATE {table} SET v = v + 1 RETURNING id")
        };
        setup(&fixture, &statements).await;
        let outcome = run(&engine, &fixture, SqlJob::new(ConnectionId::new(), sql)).await;
        assert_eq!(outcome.state, RunState::Succeeded, "{:?}", outcome.error);
        assert!(!outcome.effect_unknown);
        assert!(outcome.truncated);
        assert_eq!(outcome.data.row_count(), 1_000);
        assert_eq!(outcome.rows_discarded, 9_000);
        assert!(outcome.completion.is_some());
        assert_eq!(
            scalar(&engine, &fixture, distinct_v(&fixture, &table))
                .await
                .as_deref(),
            Some("1"),
            "every row updated, once"
        );
        let mut cleanup = vec![format!("DROP TABLE {table}")];
        if mysql(&fixture) {
            cleanup.push(format!("DROP PROCEDURE {procedure}"));
        }
        setup(&fixture, &cleanup).await;
    }

    /// E3: the same kind of write with a deadline shorter than its result
    /// fails with `Timeout` and its effect unknown, and nothing runs it
    /// again.
    #[tokio::test]
    #[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
    async fn a_job_write_past_its_deadline_is_never_run_again() {
        let fixture = fixture();
        let engine = Engine::new(tokio::runtime::Handle::current());
        let table = name("job_e3");
        let procedure = name("job_e3_p");
        let mut statements = numbers(&fixture, &table);
        let sql = if mysql(&fixture) {
            statements.push(format!(
                "CREATE PROCEDURE {procedure}() BEGIN UPDATE {table} SET v = v + 1; \
                 SELECT id, SLEEP(0.001) FROM {table} ORDER BY id; END"
            ));
            format!("CALL {procedure}()")
        } else {
            format!("UPDATE {table} SET v = v + 1 RETURNING id, pg_sleep(0.001)")
        };
        setup(&fixture, &statements).await;
        let mut job = SqlJob::new(ConnectionId::new(), sql);
        job.timeout = Duration::from_millis(500);
        let outcome = run(&engine, &fixture, job).await;
        assert_eq!(outcome.state, RunState::Failed);
        assert_eq!(outcome.cause, Some(Cause::Timeout));
        assert!(outcome.effect_unknown);
        let values = scalar(&engine, &fixture, distinct_v(&fixture, &table)).await;
        assert!(matches!(values.as_deref(), Some("0" | "1")), "{values:?}");
        let mut cleanup = vec![format!("DROP TABLE {table}")];
        if mysql(&fixture) {
            cleanup.push(format!("DROP PROCEDURE {procedure}"));
        }
        setup(&fixture, &cleanup).await;
    }

    /// E5: a job on the connection of a tab holding an open transaction
    /// commits its own write and leaves the tab's transaction as it was.
    #[tokio::test]
    #[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
    async fn a_job_leaves_a_tab_transaction_alone() {
        let fixture = fixture();
        let engine = Engine::new(tokio::runtime::Handle::current());
        let (a, b) = (name("job_e5_a"), name("job_e5_b"));
        setup(
            &fixture,
            &[
                format!("CREATE TABLE {a} (id INTEGER)"),
                format!("CREATE TABLE {b} (id INTEGER)"),
            ],
        )
        .await;
        let mut tab = fixture
            .driver
            .open_session(&fixture.input, CancellationToken::new())
            .await
            .unwrap();
        on(&mut tab, "BEGIN").await;
        on(&mut tab, &format!("INSERT INTO {a} VALUES (1)")).await;
        let write = run(
            &engine,
            &fixture,
            SqlJob::new(ConnectionId::new(), format!("INSERT INTO {b} VALUES (1)")),
        )
        .await;
        assert_eq!(write.state, RunState::Succeeded, "{:?}", write.error);
        assert!(!write.effect_unknown);
        let count_a = format!("SELECT count(*) FROM {a}");
        assert_eq!(
            scalar(&engine, &fixture, count_a.clone()).await.as_deref(),
            Some("0")
        );
        assert!(matches!(
            tab.transaction(CancellationToken::new()).await.unwrap(),
            Some(TransactionStatus::Open { .. })
        ));
        assert_eq!(on(&mut tab, &count_a).await.value(0, 0), Some("1"));
        on(&mut tab, "ROLLBACK").await;
        tab.close().await.unwrap();
        assert_eq!(
            scalar(&engine, &fixture, count_a).await.as_deref(),
            Some("0")
        );
        assert_eq!(
            scalar(&engine, &fixture, format!("SELECT count(*) FROM {b}"))
                .await
                .as_deref(),
            Some("1")
        );
        setup(
            &fixture,
            &[format!("DROP TABLE {a}"), format!("DROP TABLE {b}")],
        )
        .await;
    }

    /// E9: duplicate column names in order, an exact decimal, NULL and the
    /// text `NULL`.
    #[tokio::test]
    #[ignore = "live: needs JYKRE_TEST_DRIVER and JYKRE_TEST_PORT from cargo xtask check --full"]
    async fn a_job_result_keeps_names_decimals_and_null() {
        let fixture = fixture();
        let engine = Engine::new(tokio::runtime::Handle::current());
        let sql = "SELECT x.n AS id, y.n AS id, \
                   CAST('12345678901234567890.123456789012345678' AS DECIMAL(38, 18)) AS d, \
                   NULL AS nul, 'NULL' AS txt FROM (SELECT 1 AS n) AS x, (SELECT 2 AS n) AS y";
        let outcome = run(&engine, &fixture, SqlJob::new(ConnectionId::new(), sql)).await;
        assert_eq!(outcome.state, RunState::Succeeded, "{:?}", outcome.error);
        let data = &outcome.data;
        let names: Vec<&str> = data.columns().iter().map(|c| c.name.as_str()).collect();
        assert_eq!(names, ["id", "id", "d", "nul", "txt"]);
        assert_eq!((data.value(0, 0), data.value(0, 1)), (Some("1"), Some("2")));
        assert_eq!(
            data.value(0, 2),
            Some("12345678901234567890.123456789012345678")
        );
        assert!(data.is_null(0, 3));
        assert_eq!(data.value(0, 4), Some("NULL"));
        assert!(!data.is_null(0, 4));
    }
}
